$hoActive='reviews';$hoTitle='Reviews';$hoOwnerName=$ownerName;$hoPendingBadge=HoGetPendingCount($pdo,$hotelId);$hoUnreadBadge=HoGetUnreadCount($pdo,$hotelId);$hoNotifItems=HoGetNotificationItems($pdo,8,$hotelId);
ensureHotelReviewManagementColumns($pdo);header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
function hre(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
function hrJson(int $code,bool $success,string $message):never{http_response_code($code);header('Content-Type:application/json');echo json_encode(['success'=>$success,'message'=>$message]);exit;}
function hrUrl(int $page):string{$query=$_GET;unset($query['export']);$query['page']=$page;return'Horeviews.php?'.http_build_query($query);}
if(empty($_SESSION['hotel_reviews_csrf']))$_SESSION['hotel_reviews_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['hotel_reviews_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf_token']??'')))hrJson(403,false,'Your security token expired. Refresh and try again.');
 $allowed=['published','hidden','flagged'];$action=strtolower(trim((string)($_POST['action']??'update')));
 if($action==='bulk'){$status=strtolower(trim((string)($_POST['status']??'')));$rawIds=$_POST['review_ids']??null;if(!is_array($rawIds)||!$rawIds||count($rawIds)>100)hrJson(422,false,'Select reviews and a valid bulk action.');$ids=[];foreach($rawIds as$rawId){if(!is_string($rawId)||!preg_match('/^[1-9]\d*$/D',$rawId))hrJson(422,false,'Select reviews and a valid bulk action.');$id=filter_var($rawId,FILTER_VALIDATE_INT);if($id===false)hrJson(422,false,'Select reviews and a valid bulk action.');$ids[]=$id;}$ids=array_values(array_unique($ids));if(!in_array($status,$allowed,true)||!$ids)hrJson(422,false,'Select reviews and a valid bulk action.');$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("UPDATE hotel_resort_reviews SET moderation_status=?,responded_by=?,responded_at=NOW() WHERE hotel_resort_id=? AND review_id IN ({$marks})");$stmt->execute(array_merge([$status,$hotelAdminId,$hotelId],$ids));logActivity($pdo,'Hotel Owner',$hotelAdminId,$actorName,'Hotel Reviews Moderated',ucfirst($status).' '.$stmt->rowCount().' review(s) for '.$propertyName.'.','Hotel Reviews',null);hrJson(200,true,$stmt->rowCount().' review(s) updated.');}
 $id=(int)($_POST['review_id']??0);$status=strtolower(trim((string)($_POST['moderation_status']??'')));$reply=trim((string)($_POST['owner_reply']??''));$note=trim((string)($_POST['internal_note']??''));
 if($id<1||!in_array($status,$allowed,true))hrJson(422,false,'Select a valid review status.');if(mb_strlen($reply)>2000||mb_strlen($note)>3000)hrJson(422,false,'The response or internal note is too long.');
 $stmt=$pdo->prepare('UPDATE hotel_resort_reviews SET moderation_status=?,owner_reply=?,internal_note=?,responded_by=?,responded_at=NOW() WHERE review_id=? AND hotel_resort_id=?');$stmt->execute([$status,$reply!==''?$reply:null,$note!==''?$note:null,$hotelAdminId,$id,$hotelId]);if(!$stmt->rowCount()){$check=$pdo->prepare('SELECT COUNT(*) FROM hotel_resort_reviews WHERE review_id=? AND hotel_resort_id=?');$check->execute([$id,$hotelId]);if(!(int)$check->fetchColumn())hrJson(404,false,'Review not found for this property.');}
 logActivity($pdo,'Hotel Owner',$hotelAdminId,$actorName,'Hotel Review Updated','Updated review #'.$id.' for '.$propertyName.' to '.$status.'.','Hotel Reviews',$id);hrJson(200,true,'Review updated successfully.');
}
$search=trim((string)($_GET['search']??''));$roomId=(int)($_GET['room']??0);$rating=(int)($_GET['rating']??0);$status=strtolower(trim((string)($_GET['status']??'')));$period=strtolower(trim((string)($_GET['period']??'all')));$sort=strtolower(trim((string)($_GET['sort']??'newest')));$page=max(1,(int)($_GET['page']??1));$perPage=12;
$where=['r.hotel_resort_id=:hotel_id'];$params=[':hotel_id'=>$hotelId];$statuses=['published','hidden','flagged'];if($search!==''){$where[]='(r.reviewer_name LIKE :search OR r.review_message LIKE :search OR t.email LIKE :search OR b.booking_reference LIKE :search OR COALESCE(room.room_name,b.room_type) LIKE :search)';$params[':search']='%'.$search.'%';}
$roomsStmt=$pdo->prepare('SELECT hotel_room_id,room_name FROM hotel_rooms WHERE hotel_resort_id=? ORDER BY room_name');$roomsStmt->execute([$hotelId]);$rooms=$roomsStmt->fetchAll(PDO::FETCH_ASSOC);$roomIds=array_map(fn($row)=>(int)$row['hotel_room_id'],$rooms);if($roomId>0&&in_array($roomId,$roomIds,true)){$where[]='b.hotel_room_id=:room_id';$params[':room_id']=$roomId;}else$roomId=0;
if($rating>=1&&$rating<=5){$where[]='ROUND(r.rating)=:rating';$params[':rating']=$rating;}else$rating=0;if(in_array($status,$statuses,true)){$where[]='r.moderation_status=:status';$params[':status']=$status;}else$status='';
$periodDays=['7d'=>7,'30d'=>30,'90d'=>90];if(isset($periodDays[$period]))$where[]='r.created_at>=DATE_SUB(NOW(),INTERVAL '.$periodDays[$period].' DAY)';else$period='all';$orders=['newest'=>'r.created_at DESC','oldest'=>'r.created_at ASC','highest'=>'r.rating DESC,r.created_at DESC','lowest'=>'r.rating ASC,r.created_at DESC'];if(!isset($orders[$sort]))$sort='newest';
$from=' FROM hotel_resort_reviews r LEFT JOIN tourist t ON t.tourist_id=r.tourist_id LEFT JOIN hotel_room_bookings b ON b.hotel_booking_id=r.hotel_booking_id AND b.hotel_resort_id=r.hotel_resort_id LEFT JOIN hotel_rooms room ON room.hotel_room_id=b.hotel_room_id AND room.hotel_resort_id=r.hotel_resort_id';$whereSql=' WHERE '.implode(' AND ',$where);
$count=$pdo->prepare('SELECT COUNT(*)'.$from.$whereSql);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$select='SELECT r.*,t.full_name tourist_name,t.email tourist_email,t.phone_number tourist_phone,t.address tourist_address,t.profile_picture tourist_profile,b.booking_reference,b.room_type,b.checkin_date,b.checkout_date,b.nights,b.rooms_booked,b.adults,b.children,COALESCE(room.room_name,b.room_type,"Room stay") room_name';$stmt=$pdo->prepare($select.$from.$whereSql.' ORDER BY '.$orders[$sort]." LIMIT {$perPage} OFFSET {$offset}");$stmt->execute($params);$reviews=$stmt->fetchAll(PDO::FETCH_ASSOC);foreach($reviews as&$review)$review['profile_url']=hotelReviewProfileImage((string)($review['tourist_profile']??''));unset($review);
$summaryStmt=$pdo->prepare("SELECT COUNT(*) review_count,ROUND(COALESCE(AVG(rating),0),1) average_rating,SUM(ROUND(rating)=5) five_star,SUM(moderation_status='flagged') flagged,SUM(owner_reply IS NOT NULL AND TRIM(owner_reply)<>'') replied,SUM(created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) recent FROM hotel_resort_reviews WHERE hotel_resort_id=?");$summaryStmt->execute([$hotelId]);$summary=$summaryStmt->fetch(PDO::FETCH_ASSOC)?:[];
$distStmt=$pdo->prepare('SELECT ROUND(rating) stars,COUNT(*) total FROM hotel_resort_reviews WHERE hotel_resort_id=? GROUP BY ROUND(rating)');$distStmt->execute([$hotelId]);$distribution=$distStmt->fetchAll(PDO::FETCH_KEY_PAIR);$aspectStmt=$pdo->prepare('SELECT ROUND(COALESCE(AVG(location_rating),0),1) location,ROUND(COALESCE(AVG(service_rating),0),1) service,ROUND(COALESCE(AVG(value_rating),0),1) value_score,ROUND(COALESCE(AVG(cleanliness_rating),0),1) cleanliness,ROUND(COALESCE(AVG(facilities_rating),0),1) facilities,ROUND(COALESCE(AVG(room_comfort_rating),0),1) comfort FROM hotel_resort_reviews WHERE hotel_resort_id=?');$aspectStmt->execute([$hotelId]);$aspects=$aspectStmt->fetch(PDO::FETCH_ASSOC)?:[];$allTotal=max(1,(int)($summary['review_count']??0));$responseRate=round(((int)($summary['replied']??0)/$allTotal)*100);
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="property-reviews-'.date('Y-m-d').'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Review ID','Guest','Email','Booking','Room','Stay','Overall','Location','Service','Value','Cleanliness','Facilities','Room Comfort','Review','Status','Owner Response','Submitted']);foreach($reviews as$r)fputcsv($out,[$r['review_id'],$r['tourist_name']?:$r['reviewer_name'],$r['tourist_email'],$r['booking_reference'],$r['room_name'],trim((string)$r['checkin_date'].' to '.(string)$r['checkout_date']),$r['rating'],$r['location_rating'],$r['service_rating'],$r['value_rating'],$r['cleanliness_rating'],$r['facilities_rating'],$r['room_comfort_rating'],$r['review_message'],$r['moderation_status'],$r['owner_reply'],$r['created_at']]);fclose($out);exit;}$hasFilters=$search!==''||$roomId>0||$rating>0||$status!==''||$period!=='all';
